package app.loveu;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
public final class Analytics {
 public static class Summary {
  public Long shortestDurationMillis,longestDurationMillis,totalDurationMillis; public Domain.Stats base; public Map<String,Integer> monthly=new TreeMap<>(),dateCounts=new TreeMap<>(),places=new TreeMap<>(),protectionCounts=new TreeMap<>(),outcomeCounts=new TreeMap<>(),positionCounts=new TreeMap<>(),vocalCounts=new TreeMap<>(),selfBodyTags=new TreeMap<>(),partnerBodyTags=new TreeMap<>();
  public int[] weekdays=new int[7],hours=new int[24],durationBins=new int[5],intervalBins=new int[5]; public int knownTimes,partnerKnown,selfKnown,partnerCountKnown,selfCountKnown,selfConditionKnown,partnerConditionKnown,selfComfortKnown,partnerComfortKnown; public Double partnerOrgasmRate,selfOrgasmRate,selfComfortMean,partnerComfortMean;
 }
 public static class Comparison {public int current,previous,delta;public Double percent;}
 private static void add(Map<String,Integer> m,String key){if(key!=null&&!key.isEmpty())m.put(key,m.getOrDefault(key,0)+1);}
 private static void tags(Map<String,Integer> m,List<String> tags){for(String tag:new HashSet<>(tags))add(m,tag);}
 private static boolean known(Domain.Condition c){return c.energy!=null||c.fatigue!=null||c.mood!=null||c.comfort!=null||!c.tags.isEmpty();}
 private static List<Domain.Event> select(List<Domain.Event> events,LocalDate start,LocalDate end){if(start!=null&&end!=null&&start.isAfter(end))throw new IllegalArgumentException("Invalid range");List<Domain.Event> out=new ArrayList<>();for(Domain.Event e:events){LocalDate d=LocalDate.parse(Domain.validateDate(e.date));if((start==null||!d.isBefore(start))&&(end==null||!d.isAfter(end)))out.add(e);}return out;}
 public static Summary analyze(List<Domain.Event> events,LocalDate start,LocalDate end){Summary s=new Summary();List<Domain.Event> chosen=select(events,start,end);s.base=Domain.stats(chosen);s.monthly.putAll(s.base.monthCounts);int pYes=0,selfYes=0,sc=0,pc=0;double sv=0,pv=0;for(Domain.Event e:chosen){Domain.validateEvent(e);LocalDate d=LocalDate.parse(e.date);add(s.dateCounts,e.date);s.weekdays[d.getDayOfWeek().getValue()-1]++;if(e.time!=null){s.hours[LocalTime.parse(e.time).getHour()]++;s.knownTimes++;}if(e.durationMillis!=null){long n=e.durationMillis;s.shortestDurationMillis=s.shortestDurationMillis==null?n:Math.min(s.shortestDurationMillis,n);s.longestDurationMillis=s.longestDurationMillis==null?n:Math.max(s.longestDurationMillis,n);s.totalDurationMillis=s.totalDurationMillis==null?n:Math.addExact(s.totalDurationMillis,n);s.durationBins[n<300000?0:n<900000?1:n<1800000?2:n<3600000?3:4]++;}add(s.places,e.place);add(s.protectionCounts,e.protection);add(s.vocalCounts,e.vocalLevel);tags(s.outcomeCounts,e.outcomes);tags(s.positionCounts,e.positions);tags(s.selfBodyTags,e.selfCondition.tags);tags(s.partnerBodyTags,e.partnerCondition.tags);if(e.partnerOrgasm!=null){s.partnerKnown++;if(e.partnerOrgasm)pYes++;}if(e.selfOrgasm!=null){s.selfKnown++;if(e.selfOrgasm)selfYes++;}if(e.partnerOrgasmCount!=null)s.partnerCountKnown++;if(e.selfOrgasmCount!=null)s.selfCountKnown++;if(known(e.selfCondition))s.selfConditionKnown++;if(known(e.partnerCondition))s.partnerConditionKnown++;if(e.selfCondition.comfort!=null){sc++;sv+=e.selfCondition.comfort;}if(e.partnerCondition.comfort!=null){pc++;pv+=e.partnerCondition.comfort;}}
  LocalDate previous=null;for(String date:s.dateCounts.keySet()){LocalDate d=LocalDate.parse(date);if(previous!=null){long gap=ChronoUnit.DAYS.between(previous,d);s.intervalBins[gap==1?0:gap<7?1:gap<14?2:gap<30?3:4]++;}previous=d;}s.partnerOrgasmRate=s.partnerKnown==0?null:100.0*pYes/s.partnerKnown;s.selfOrgasmRate=s.selfKnown==0?null:100.0*selfYes/s.selfKnown;s.selfComfortKnown=sc;s.partnerComfortKnown=pc;s.selfComfortMean=sc==0?null:sv/sc;s.partnerComfortMean=pc==0?null:pv/pc;return s;
 }
 public static Comparison compare(List<Domain.Event> events,LocalDate start,LocalDate end,LocalDate previousStart,LocalDate previousEnd){Comparison c=new Comparison();c.current=select(events,start,end).size();c.previous=select(events,previousStart,previousEnd).size();c.delta=c.current-c.previous;c.percent=c.previous==0?null:100.0*c.delta/c.previous;return c;}
 public static class MonthExtrema {public Map<String,Integer> months=new TreeMap<>();public Integer minimum,maximum;public List<String> lowest=new ArrayList<>(),highest=new ArrayList<>();}
 /** Zero means no matching records, not an inferred absence of activity. */
 public static MonthExtrema monthExtrema(List<Domain.Event> events,Integer year,LocalDate today){
  MonthExtrema result=new MonthExtrema();YearMonth first=null,last=null;Map<String,Integer> counts=new TreeMap<>();
  for(Domain.Event e:events){YearMonth m=YearMonth.from(LocalDate.parse(Domain.validateDate(e.date)));if(m.isAfter(YearMonth.from(today)))continue;if(first==null||m.isBefore(first))first=m;if(last==null||m.isAfter(last))last=m;add(counts,m.toString());}
  if(first==null)return result;YearMonth completed=YearMonth.from(today).minusMonths(1);if(last.isAfter(completed))last=completed;
  if(year!=null){YearMonth from=YearMonth.of(year,1),to=YearMonth.of(year,12);if(from.isAfter(first))first=from;if(to.isBefore(last))last=to;}
  for(YearMonth m=first;!m.isAfter(last);m=m.plusMonths(1)){String key=m.toString();int n=counts.getOrDefault(key,0);result.months.put(key,n);if(result.minimum==null||n<result.minimum){result.minimum=n;result.lowest.clear();}if(n==result.minimum)result.lowest.add(key);if(result.maximum==null||n>result.maximum){result.maximum=n;result.highest.clear();}if(n==result.maximum)result.highest.add(key);}
  return result;
 }
 public static class YearComparison {public int[] firstMonths=new int[12],secondMonths=new int[12];public int firstTotal,secondTotal;public boolean aligned;public LocalDate firstEnd,secondEnd;}
 public static YearComparison compareYears(List<Domain.Event> events,int first,int second,boolean aligned,LocalDate today){
  YearComparison result=new YearComparison();result.aligned=aligned&&(first==today.getYear()||second==today.getYear());result.firstEnd=result.aligned?today.withYear(first):LocalDate.of(first,12,31);result.secondEnd=result.aligned?today.withYear(second):LocalDate.of(second,12,31);
  for(Domain.Event e:events){LocalDate d=LocalDate.parse(Domain.validateDate(e.date));if(d.isAfter(today))continue;if(d.getYear()==first&&!d.isAfter(result.firstEnd)){result.firstMonths[d.getMonthValue()-1]++;result.firstTotal++;}if(d.getYear()==second&&!d.isAfter(result.secondEnd)){result.secondMonths[d.getMonthValue()-1]++;result.secondTotal++;}}
  return result;
 }}
